USE wildtrail_db;
CREATE TABLE IF NOT EXISTS park_images(id INT AUTO_INCREMENT PRIMARY KEY,park_id INT NOT NULL,image_url VARCHAR(700) NOT NULL,caption VARCHAR(180),credit VARCHAR(180),source_url VARCHAR(700),sort_order INT DEFAULT 0,FOREIGN KEY(park_id) REFERENCES parks(id) ON DELETE CASCADE);
ALTER TABLE wildlife_sightings ADD COLUMN IF NOT EXISTS latitude DECIMAL(10,7) NULL AFTER photo, ADD COLUMN IF NOT EXISTS longitude DECIMAL(10,7) NULL AFTER latitude;
UPDATE parks SET image_url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Yala%20National%20Park%2C%20Sri%20Lanka.jpg?width=1600' WHERE slug='yala';
UPDATE parks SET image_url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Landscape%20in%20Udawalawe%20National%20Park%2C%20Sri%20Lanka.jpg?width=1600' WHERE slug='udawalawe';
UPDATE parks SET image_url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Minneriya%20National%20Park%2C%20Sri%20Lanka.jpg?width=1600' WHERE slug='minneriya';
UPDATE parks SET image_url='https://commons.wikimedia.org/wiki/Special:Redirect/file/Amazing%20Natural%20Landscapes.jpg?width=1600' WHERE slug='wilpattu';
SELECT p.id,'https://commons.wikimedia.org/wiki/Special:Redirect/file/Yala%20National%20Park%2C%20Sri%20Lanka.jpg?width=1600','Wetland landscape in Yala','Charles J. Sharp','https://commons.wikimedia.org/wiki/File:Yala_National_Park,_Sri_Lanka.jpg',1 FROM parks p WHERE p.slug='yala' AND NOT EXISTS(SELECT 1 FROM park_images i WHERE i.park_id=p.id);
