INSERT INTO park_images(park_id,image_url,caption,credit,source_url,sort_order) SELECT p.id,'https://commons.wikimedia.org/wiki/Special:Redirect/file/Leopard%20in%20the%20Yala%20National%20Park.jpg?width=1600','Sri Lankan leopard in Yala','Wikimedia Commons contributor','https://commons.wikimedia.org/wiki/File:Leopard_in_the_Yala_National_Park.jpg',2 FROM parks p WHERE p.slug='yala' AND (SELECT COUNT(*) FROM park_images i WHERE i.park_id=p.id)<2;
